export const SalesGrossProfitCostAllocationVoid = defineAction({
  name: 'sales_gross_profit_cost_allocation_void',
  label: '冲销已批准配比',
  objectName: 'forge_sales_gross_profit_cost_allocation',
  icon: 'undo-2',
  locations: ['record_header', 'record_more'],
  order: 90,
  visible: `record.status == 'approved'`,
  requiredPermissions: ['forge_finance_reviewer'],
  description: '冲销已批准成本配比会释放对应来源预算，并使相关收入确认期间的毛利重新计算。请填写冲销原因。',
  successMessage: '成本配比已冲销，来源预算已释放',
  refreshAfter: true,
  params: [{ name: 'void_reason', label: '冲销原因', type: 'textarea', required: true }],
  body: { language: 'js', capabilities: ['api.read', 'api.write', 'api.transaction'], source: `
const id=String(ctx.recordId||ctx.record&&ctx.record.id||'').trim(),actor=String(ctx.user&&ctx.user.id||ctx.session&&ctx.session.userId||'').trim(),org=String(ctx.user&&ctx.user.organizationId||ctx.session&&ctx.session.organizationId||'').trim(),reason=String(ctx.input.void_reason||'').trim();
if(!id||ctx.recordLoadDenied===true||!actor||!org)throw new Error('无法确认成本配比、操作人或组织');
if(!reason)throw new Error('冲销原因不能为空');
return await ctx.api.transaction(async()=>{
 const current=await ctx.api.object('forge_sales_gross_profit_cost_allocation').findOne({where:{id,organization_id:org}});
 if(!current||current.status!=='approved')throw new Error('仅已批准成本配比可以冲销');
 if(String(current.submitted_by||'')===actor)throw new Error('成本配比提交人不能自行冲销，请由另一名财务复核人员办理');
 const changed=await ctx.api.object('forge_sales_gross_profit_cost_allocation').update({id,status:'voided',void_reason:reason,voided_by:actor,voided_at:new Date().toISOString()});
 if(!changed)throw new Error('成本配比状态未能更新，请刷新后重试');
 return{id,status:'voided',budget_id:current.budget_id,source_amount:Number(current.source_amount||0)};
});
` },
});

